## ---- 01: Common Random Numbers  (qmd line 247) ---------------------------------------

n_paths <- 500; n_steps <- 360; n_factors <- 3
bump_size <- 1e-4                      # 1 bp

# Stand-in for the valuation pipeline: simulate from params using the
# supplied shocks, then value. The point is that `shocks` enters as an
# argument rather than being drawn inside.
simulate_and_value <- function(params, shocks) {
  r <- params$r0 + apply(shocks[, , 1], 1, cumsum) * params$sigma
  mean(colSums(exp(-r / 12) * 100 / n_steps))
}
params            <- list(r0 = 0.04, sigma = 0.01)
params_bumped_up  <- modifyList(params, list(r0 = 0.04 + bump_size))
params_bumped_down <- modifyList(params, list(r0 = 0.04 - bump_size))

# Pre-generate shocks once
set.seed(42)
shocks <- array(rnorm(n_paths * n_steps * n_factors),
                dim = c(n_paths, n_steps, n_factors))

# Each valuation uses the same shocks
V_base <- simulate_and_value(params, shocks)
V_up   <- simulate_and_value(params_bumped_up, shocks)
V_down <- simulate_and_value(params_bumped_down, shocks)

# Duration is the finite difference
duration <- -(V_up - V_down) / (2 * bump_size * V_base)


## ---- 02: Worked Numerical Example  (qmd line 284) ------------------------------------

sim_ou_exact <- function(X0, kappa, theta, sigma, dt, n_steps, n_paths) {
  paths <- matrix(0, n_paths, n_steps + 1)
  paths[, 1] <- X0
  mean_fac <- exp(-kappa * dt)
  var_fac <- sigma^2 * (1 - exp(-2 * kappa * dt)) / (2 * kappa)
  for (t in seq_len(n_steps)) {
    mu_t  <- theta + (paths[, t] - theta) * mean_fac
    paths[, t + 1] <- rnorm(n_paths, mean = mu_t, sd = sqrt(var_fac))
  }
  paths
}

paths <- sim_ou_exact(0.045, 0.3, 0.04, 0.015, 1/12, 60, 500)


## ---- 03: Exact OU Simulation  (qmd line 314) -----------------------------------------

sim_ou_exact <- function(X0, kappa, theta, sigma, dt, n_steps, n_paths) {
  paths <- matrix(0, n_paths, n_steps + 1)
  paths[, 1] <- X0
  m <- exp(-kappa * dt)
  v <- sigma^2 * (1 - exp(-2 * kappa * dt)) / (2 * kappa)
  for (t in seq_len(n_steps)) {
    mu_t <- theta + (paths[, t] - theta) * m
    paths[, t + 1] <- rnorm(n_paths, mu_t, sqrt(v))
  }
  paths
}

set.seed(42)
ps <- sim_ou_exact(0.045, 0.30, 0.04, 0.015, 1/12, 60, 500)

library(ggplot2)
library(tidyr)
paths_df <- as.data.frame(t(ps[1:20, ]))
paths_df$step <- seq_len(nrow(paths_df)) - 1
paths_long <- pivot_longer(paths_df, -step,
                           names_to = "path", values_to = "rate")
ggplot(paths_long, aes(step, rate, group = path)) +
  geom_line(colour = "grey60", linewidth = 0.3) +
  labs(x = "Month", y = "Short rate") +
  theme_minimal()


## ---- 04: Euler-Maruyama vs Exact  (qmd line 344) -------------------------------------

sim_ou_euler <- function(X0, kappa, theta, sigma, dt, n_steps, n_paths) {
  paths <- matrix(0, n_paths, n_steps + 1)
  paths[, 1] <- X0
  for (t in seq_len(n_steps)) {
    drift  <- kappa * (theta - paths[, t]) * dt
    diffu  <- sigma * sqrt(dt) * rnorm(n_paths)
    paths[, t + 1] <- paths[, t] + drift + diffu
  }
  paths
}

set.seed(42); pe <- sim_ou_euler(0.045, 0.30, 0.04, 0.015, 1/12, 60, 500)
mean(ps[, 60]) ; mean(pe[, 60])     # both ≈ 0.0411
sd(ps[, 60])   ; sd(pe[, 60])       # both ≈ 0.019


## ---- 05: Cholesky for Correlated Multivariate  (qmd line 363) ------------------------

# 3-factor DNS shocks
sigma <- c(0.005, 0.012, 0.020)
R <- matrix(c(1, -0.35, 0.20,
              -0.35, 1, -0.40,
              0.20, -0.40, 1), 3, 3)
Sigma <- diag(sigma) %*% R %*% diag(sigma)
L <- t(chol(Sigma))

# One step of correlated shocks
n_paths <- 500
Z <- matrix(rnorm(3 * n_paths), 3, n_paths)
shocks <- L %*% Z      # shocks now have covariance Sigma
cor(t(shocks))


